def inject(s, lang, kv):
    m = re.search(r'\n(\s*)' + re.escape(lang) + r':\s*\{', s)
    if not m:
        return s, False
    ins = m.end()
    payload = ''.join('"%s":%s,' % (k, json.dumps(v, ensure_ascii=False)) for k, v in kv.items())
    return s[:ins] + payload + s[ins:], True

def main():
    s = io.open(SP, encoding='utf-8').read()
    report = {}
    for lang in ['ta', 'bn', 'te', 'mr', 'gu', 'kn', 'ml']:
        s, ok = inject(s, lang, S[lang])
        report[lang] = [ok, len(S[lang])]
    io.open(SP, 'w', encoding='utf-8').write(s)
    sys.stdout.buffer.write((json.dumps(report) + '\n').encode('utf-8'))

if __name__ == '__main__':
    main()
